                    name="phone"
                    type="tel"
                    autoComplete="tel"
                    value={formData.phone}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    aria-invalid={showError("phone") && errors.phone ? "true" : "false"}
                    aria-describedby="phone-helper phone-error"
                  />
                  <div id="phone-helper" className="helper">
