                    name="email"
                    type="email"
                    autoComplete="email"
                    value={formData.email}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    aria-invalid={showError("email") && errors.email ? "true" : "false"}
                    aria-describedby="email-error"
                    required
                  />
                  <div id="email-error" className="error" role="alert" aria-live="polite">
                    {showError("email") ? errors.email || "" : ""}
                  </div>
                </div>

                <div className="form-field">
                  <label htmlFor="phone">Phone number</label>
                  <input
                    id="phone"
                    name="phone"
                    type="tel"
                    autoComplete="tel"
                    value={formData.phone}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    aria-invalid={showError("phone") && errors.phone ? "true" : "false"}
                    aria-describedby="phone-helper phone-error"
                  />
                  <div id="phone-helper" className="helper">
                    Include country code if needed, for example +1 555 123 4567.
                  </div>
                  <div id="phone-error" className="error" role="alert" aria-live="polite">
                    {showError("phone") ? errors.phone || "" : ""}
                  </div>
                </div>

                <button type="submit">Submit request</button>
              </form>

              {isSent ? (
                <div className="success" role="status" aria-live="polite">
                  Thanks — your message has been sent.
                </div>
              ) : null}
            </section>
          </main>
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(<SupportContactForm />);
    </script>
  </body>
</html>
