       function SupportContactForm() {
         const [formData, setFormData] = useState({
           fullName: "",
           email: "",
           phone: "",
         });
         const [touched, setTouched] = useState({});
         const [submitted, setSubmitted] = useState(false);
         const [isSent, setIsSent] = useState(false);

         const errors = useMemo(() => {
           const nextErrors = {};

           if (!formData.fullName.trim()) {
             nextErrors.fullName = "Full name is required.";
           }

           if (!formData.email.trim()) {
             nextErrors.email = "Email address is required.";
           } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email.trim())) {
             nextErrors.email = "Enter a valid email address.";
           }

           if (formData.phone.trim() && !/^[0-9()+\-\s]{7,}$/.test(formData.phone.trim())) {
             nextErrors.phone = "Enter a valid phone number.";
           }

           return nextErrors;
         }, [formData]);

         const showError = (field) => submitted || touched[field];

         function handleChange(event) {
           const { name, value } = event.target;
           setFormData((current) => ({ ...current, [name]: value }));
         }

         function handleBlur(event) {
           const { name } = event.target;
           setTouched((current) => ({ ...current, [name]: true }));
         }

         function handleSubmit(event) {
           event.preventDefault();
           setSubmitted(true);
           setTouched({ fullName: true, email: true, phone: true });

           if (Object.keys(errors).length === 0) {
             setIsSent(true);
           } else {
             setIsSent(false);
           }
         }

         return (
           <main className="page">
             <section className="card" aria-labelledby="support-contact-title">
               <p className="eyebrow">Support</p>
               <h1 id="support-contact-title">Contact our team</h1>
               <p className="subtitle">
                 Send us a message and we&apos;ll get back to you with the help you need.
               </p>

               <form onSubmit={handleSubmit} noValidate>
                 <div className="form-field">
                   <label htmlFor="fullName">Full name</label>
                   <input
                     id="fullName"
                     name="fullName"
                     type="text"
                     autoComplete="name"
                     value={formData.fullName}
                     onChange={handleChange}
                     onBlur={handleBlur}
                     aria-invalid={showError("fullName") && errors.fullName ? "true" : "false"}
                     aria-describedby="fullName-error"
                     required
                   />
                   <div id="fullName-error" className="error" role="alert" aria-live="polite">
                     {showError("fullName") ? errors.fullName || "" : ""}
                   </div>
')

